import { writeFileSync } from "node:fs";
import path from "node:path";
import openapiTS, { astToString } from "openapi-typescript";

async function main() {
	const schemaPath = path.resolve(
		__dirname,
		"../../../schemas/openapi-v1.json",
	);
	const outputPath = path.resolve(__dirname, "../src/types/openapi.ts");

	console.log(`Reading OpenAPI 3.1 schema from: ${schemaPath}`);
	const schemaUrl = new URL(`file:///${schemaPath.replace(/\\/g, "/")}`);
	const ast = await openapiTS(schemaUrl);
	const tsContent = astToString(ast);

	const banner = `/**
 * Auto-generated by @opendv/protocol-ts codegen from schemas/openapi-v1.json.
 * DO NOT EDIT MANUALLY. Run \`bun run codegen\` to regenerate.
 */\n\n`;

	writeFileSync(outputPath, banner + tsContent, "utf-8");
	try {
		const { execSync } = await import("node:child_process");
		execSync(`bun x biome format --write "${outputPath}"`, { stdio: "pipe" });
	} catch {
		// Ignore if biome is unavailable
	}
	console.log(`Successfully generated TypeScript types at: ${outputPath}`);
}

main().catch((err) => {
	console.error("Error generating TypeScript types:", err);
	process.exit(1);
});
